    buy_book = []  # List of (price, arrival_time, id, qty) - descending by price, then ascending by arrival_time
    sell_book = []  # List of (price, arrival_time, id, qty) - ascending by price, then ascending by arrival_time
    order_map = {}  # Map id -> (side, price, qty, arrival_time) for tracking resting orders
    next_arrival_time = [0]  # Counter for arrival times

    def add_to_buy_book(price, id, qty):
        # Buy book sorted by: price descending, then arrival_time ascending
        import bisect
        # We need to insert in reverse order for price, so use negative price for bisect
        buy_book.append((price, next_arrival_time[0] - 1, id, qty))
        buy_book.sort(key=lambda x: (-x[0], x[1]))

    def add_to_sell_book(price, id, qty):
        # Sell book sorted by: price ascending, then arrival_time ascending
        import bisect
        sell_book.append((price, next_arrival_time[0] - 1, id, qty))
        sell_book.sort(key=lambda x: (x[0], x[1]))

    def match_buy(price, id, qty, is_ioc_or_market):
        nonlocal trades
        remaining = qty
        i = 0
        while i < len(sell_book) and remaining > 0:
            sell_price, sell_arrival, sell_id, sell_qty = sell_book[i]
            if sell_price <= price:
                trade_qty = min(remaining, sell_qty)
                trades.append([id, sell_id, sell_price, trade_qty])
                remaining -= trade_qty
                sell_book[i] = (sell_price, sell_arrival, sell_id, sell_qty - trade_qty)
                if sell_book[i][3] == 0:
                    sell_book.pop(i)
                else:
                    i += 1
            else:
                break

        if remaining > 0 and not is_ioc_or_market:
            add_to_buy_book(price, id, remaining)

    def match_sell(price, id, qty, is_ioc_or_market):
        nonlocal trades
        remaining = qty
        i = 0
        while i < len(buy_book) and remaining > 0:
            buy_price, buy_arrival, buy_id, buy_qty = buy_book[i]
            if buy_price >= price:
                trade_qty = min(remaining, buy_qty)
                trades.append([buy_id, id, buy_price, trade_qty])
                remaining -= trade_qty
                buy_book[i] = (buy_price, buy_arrival, buy_id, buy_qty - trade_qty)
                if buy_book[i][3] == 0:
                    buy_book.pop(i)
                else:
                    i += 1
            else:
                break

        if remaining > 0 and not is_ioc_or_market:
            add_to_sell_book(price, id, remaining)

    for order in orders:
        next_arrival_time[0] += 1

        if order[0] == 'limit':
            _, id, side, price, qty = order
            if side == 'buy':
                match_buy(price, id, qty, False)
            else:
                match_sell(price, id, qty, False)

        elif order[0] == 'ioc':
            _, id, side, price, qty = order
            if side == 'buy':
                match_buy(price, id, qty, True)
            else:
                match_sell(price, id, qty, True)

        elif order[0] == 'market':
            _, id, side, qty = order
